code_examples.python:
import requests

headers = {"X-API-Key": "YOUR_KEY"}
data = {
    "schema_type": "users",
    "count": 10,
    "locale": "ru_RU"
}

response = requests.post(
    "https://tdd-api-4daf.onrender.com/generate",
    json=data,
    headers=headers
)
print(response.json()["data"][0]["name"])

code_examples.javascript:
fetch('https://tdd-api-4daf.onrender.com/generate', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'X-API-Key': 'YOUR_KEY'
  },
  body: JSON.stringify({
    schema_type: 'users',
    count: 10,
    locale: 'en_US'
  })
}).then(r => r.json())
.then(data => console.log(data.data[0].name));
